import{_ as p,a0 as d,w as o,s as r,I as a,x as n,a1 as t,A as e,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"在 Linux 中自动配置 IPv6 地址 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中自动配置 IPv6 地址 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中自动配置 IPv6 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中自动配置 IPv6 地址 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20171214 IPv6 Auto-Configuration in Linux","title":"在 Linux 中自动配置 IPv6 地址","tag":"201803","desc":""},"relativePath":"201803/20171214 IPv6 Auto-Configuration in Linux.md","filePath":"[post].md"}'),u={name:"201803/20171214 IPv6 Auto-Configuration in Linux.md"};function g(v,s,f,b,k,c){const i=d("Link");return o(),r("div",null,[s[30]||(s[30]=a("h1",{id:"在-linux-中自动配置-ipv6-地址",tabindex:"-1"},[n("在 Linux 中自动配置 IPv6 地址 "),a("a",{class:"header-anchor",href:"#在-linux-中自动配置-ipv6-地址","aria-label":"Permalink to “在 Linux 中自动配置 IPv6 地址”"},"​")],-1)),s[31]||(s[31]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner_5.png?itok=3kN83IjL",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("在 ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/11/testing-ipv6-networking-kvm-part-1"},{default:e(()=>[...s[0]||(s[0]=[n("KVM 中测试 IPv6 网络：第 1 部分",-1)])]),_:1}),s[2]||(s[2]=n(" 一文中，我们学习了关于",-1)),s[3]||(s[3]=a("ruby",null,[n("唯一本地地址"),a("rt",null,"unique local addresses")],-1)),s[4]||(s[4]=n("（ULA）的相关内容。在本文中，我们将学习如何为 ULA 自动配置 IP 地址。",-1))]),s[32]||(s[32]=l(`<h3 id="何时使用唯一本地地址" tabindex="-1">何时使用唯一本地地址 <a class="header-anchor" href="#何时使用唯一本地地址" aria-label="Permalink to “何时使用唯一本地地址”">​</a></h3><p><ruby>唯一本地地址<rt>unique local addresses</rt></ruby>（ULA）使用 <code>fd00::/8</code> 地址块，它类似于我们常用的 IPv4 的私有地址：<code>10.0.0.0/8</code>、<code>172.16.0.0/12</code>、以及 <code>192.168.0.0/16</code>。但它们并不能直接替换。IPv4 的私有地址分类和网络地址转换（NAT）功能是为了缓解 IPv4 地址短缺的问题，这是个明智的解决方案，它延缓了本该被替换的 IPv4 的生命周期。IPv6 也支持 NAT，但是我想不出使用它的理由。IPv6 的地址数量远远大于 IPv4；它是不一样的，因此需要做不一样的事情。</p><p>那么，ULA 存在的意义是什么呢？尤其是在我们已经有了<ruby>本地链路地址<rt>link-local addresses</rt></ruby>（<code>fe80::/10</code>）时，到底需不需要我们去配置它们呢？它们之间（LCTT 译注：指的是唯一本地地址和本地链路地址）有两个重要的区别。一是，本地链路地址是不可路由的，因此，你不能跨子网使用它。二是，ULA 是你自己管理的；你可以自己选择它用于子网的地址范围，并且它们是可路由的。</p><p>使用 ULA 的另一个好处是，如果你只是在局域网中“混日子”的话，你不需要为它们分配全局单播 IPv6 地址。当然了，如果你的 ISP 已经为你分配了 IPv6 的<ruby>全局单播地址<rt>global unicast addresses</rt></ruby>，就不需要使用 ULA 了。你也可以在同一个网络中混合使用全局单播地址和 ULA，但是，我想不出这样使用的一个好理由，并且要一定确保你不使用网络地址转换（NAT）以使 ULA 可公共访问。在我看来，这是很愚蠢的行为。</p><p>ULA 是仅为私有网络使用的，并且应该阻止其流出你的网络，不允许进入因特网。这很简单，在你的边界设备上只要阻止整个 <code>fd00::/8</code> 范围的 IPv6 地址即可实现。</p><h3 id="地址自动配置" tabindex="-1">地址自动配置 <a class="header-anchor" href="#地址自动配置" aria-label="Permalink to “地址自动配置”">​</a></h3><p>ULA 不像本地链路地址那样自动配置的，但是使用 radvd 设置自动配置是非常容易的，radva 是路由器公告守护程序。在你开始之前，运行 <code>ifconfig</code> 或者 <code>ip addr show</code> 去查看你现有的 IP 地址。</p><p>在生产系统上使用时，你应该将 radvd 安装在一台单独的路由器上，如果只是测试使用，你可以将它安装在你的网络中的任意 Linux PC 上。在我的小型 KVM 测试实验室中，我使用 <code>apt-get install radvd</code> 命令把它安装在 Ubuntu 上。安装完成之后，我先不启动它，因为它还没有配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status radvd</span></span>
<span class="line"><span>● radvd.service - LSB: Router Advertising Daemon</span></span>
<span class="line"><span>   Loaded: loaded (/etc/init.d/radvd; bad; vendor preset: enabled)</span></span>
<span class="line"><span>   Active: active (exited) since Mon 2017-12-11 20:08:25 PST; 4min 59s ago</span></span>
<span class="line"><span>     Docs: man:systemd-sysv-generator(8)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 systemd[1]: Starting LSB: Router Advertising Daemon...</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 radvd[3541]: Starting radvd:</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 radvd[3541]: * /etc/radvd.conf does not exist or is empty.</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 radvd[3541]: * See /usr/share/doc/radvd/README.Debian</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 radvd[3541]: * radvd will *not* be started.</span></span>
<span class="line"><span>Dec 11 20:08:25 ubunut1 systemd[1]: Started LSB: Router Advertising Daemon.</span></span></code></pre></div><p>这些所有的消息有点让人困惑，实际上 radvd 并没有运行，你可以使用经典命令 <code>ps | grep radvd</code> 来验证这一点。因此，我们现在需要去创建 <code>/etc/radvd.conf</code> 文件。拷贝这个示例，将第一行的网络接口名替换成你自己的接口名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>interface ens7 {</span></span>
<span class="line"><span>  AdvSendAdvert on;</span></span>
<span class="line"><span>  MinRtrAdvInterval 3;</span></span>
<span class="line"><span>  MaxRtrAdvInterval 10;</span></span>
<span class="line"><span>  prefix fd7d:844d:3e17:f3ae::/64</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>                AdvOnLink on;</span></span>
<span class="line"><span>                AdvAutonomous on;</span></span>
<span class="line"><span>        };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>};</span></span></code></pre></div>`,11)),a("p",null,[s[6]||(s[6]=n("前缀（",-1)),s[7]||(s[7]=a("code",null,"prefix",-1)),s[8]||(s[8]=n("）定义了你的网络地址，它是地址的前 64 位。前两个字符必须是 ",-1)),s[9]||(s[9]=a("code",null,"fd",-1)),s[10]||(s[10]=n("，前缀接下来的剩余部分你自己定义它，最后的 64 位留空，因为 radvd 将去分配最后的 64 位。前缀后面的 16 位用来定义子网，剩余的地址定义为主机地址。你的子网必须总是 ",-1)),s[11]||(s[11]=a("code",null,"/64",-1)),s[12]||(s[12]=n("。RFC 4193 要求地址必须随机生成；查看 ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/11/testing-ipv6-networking-kvm-part-1"},{default:e(()=>[...s[5]||(s[5]=[n("在 KVM 中测试 IPv6 Networking：第 1 部分",-1)])]),_:1}),s[13]||(s[13]=n(" 学习创建和管理 ULAs 的更多知识。",-1))]),s[33]||(s[33]=l(`<h3 id="ipv6-转发" tabindex="-1">IPv6 转发 <a class="header-anchor" href="#ipv6-转发" aria-label="Permalink to “IPv6 转发”">​</a></h3><p>IPv6 转发必须要启用。下面的命令去启用它，重启后生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysctl -w net.ipv6.conf.all.forwarding=1</span></span></code></pre></div><p>取消注释或者添加如下的行到 <code>/etc/sysctl.conf</code> 文件中，以使它永久生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>net.ipv6.conf.all.forwarding = 1</span></span></code></pre></div><p>启动 radvd 守护程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl stop radvd</span></span>
<span class="line"><span>$ sudo systemctl start radvd</span></span></code></pre></div><p>这个示例在我的 Ubuntu 测试系统中遇到了一个怪事；radvd 总是停止，我查看它的状态却没有任何问题，做任何改变之后都需要重新启动 radvd。</p><p>启动成功后没有任何输出，并且失败也是如此，因此，需要运行 <code>sudo systemctl status radvd</code> 去查看它的运行状态。如果有错误，<code>systemctl</code> 会告诉你。一般常见的错误都是 <code>/etc/radvd.conf</code> 中的语法错误。</p><p>在 Twitter 上抱怨了上述问题之后，我学到了一件很酷的技巧：当你运行 <code> journalctl -xe --no-pager</code> 去调试 <code>systemctl</code> 错误时，你的输出会被换行，然后，你就可以看到错误信息。</p><p>现在检查你的主机，查看它们自动分配的新地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig</span></span>
<span class="line"><span>ens7      Link encap:Ethernet  HWaddr 52:54:00:57:71:50  </span></span>
<span class="line"><span>          [...]</span></span>
<span class="line"><span>          inet6 addr: fd7d:844d:3e17:f3ae:9808:98d5:bea9:14d9/64 Scope:Global</span></span>
<span class="line"><span>          [...]</span></span></code></pre></div><p>本文到此为止，下周继续学习如何为 ULA 管理 DNS，这样你就可以使用一个合适的主机名来代替这些长长的 IPv6 地址。</p>`,13)),a("p",null,[s[15]||(s[15]=n("通过来自 Linux 基金会和 edX 的 ",-1)),t(i,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:e(()=>[...s[14]||(s[14]=[n("“Linux 入门”",-1)])]),_:1}),s[16]||(s[16]=n(" 免费课程学习更多 Linux 的知识。",-1))]),s[34]||(s[34]=a("hr",null,null,-1)),a("p",null,[s[18]||(s[18]=n("via: ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/12/ipv6-auto-configuration-linux"},{default:e(()=>[...s[17]||(s[17]=[n("https://www.linux.com/learn/intro-to-linux/2017/12/ipv6-auto-configuration-linux",-1)])]),_:1})]),a("p",null,[s[22]||(s[22]=n("作者：",-1)),t(i,{href:"https://www.linux.com/users/cschroder"},{default:e(()=>[...s[19]||(s[19]=[n("Carla Schroder",-1)])]),_:1}),s[23]||(s[23]=n(" 译者：",-1)),t(i,{href:"https://github.com/qhwdw"},{default:e(()=>[...s[20]||(s[20]=[n("qhwdw",-1)])]),_:1}),s[24]||(s[24]=n(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[21]||(s[21]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[27]||(s[27]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[25]||(s[25]=[n("LCTT",-1)])]),_:1}),s[28]||(s[28]=n(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...s[26]||(s[26]=[n("Linux中国",-1)])]),_:1}),s[29]||(s[29]=n(" 荣誉推出",-1))])])}const L=p(u,[["render",g]]);export{h as __pageData,L as default};
